query.expr:
f -> {
    kind = $f.get(`ehome.runtime:Function#kind`);
    main = if($kind == `ehome.runtime:FunctionKind#dimmer`, if($f.get(`ehome.runtime:Function#command`) != null, $f.get(`ehome.runtime:Function#command`), $f.get(`ehome.runtime:Function#levelCommand`)),
        if($kind == `ehome.runtime:FunctionKind#blind`, $f.get(`ehome.runtime:Function#move`),
        if($kind == `ehome.runtime:FunctionKind#sensor`, $f.get(`ehome.runtime:Function#value`),
        if($kind == `ehome.runtime:FunctionKind#climate`, $f.get(`ehome.runtime:Function#temperature`),
        if($kind == `ehome.runtime:FunctionKind#button`, $f.get(`ehome.runtime:Function#press`),
            $f.get(`ehome.runtime:Function#command`))))));
    $kind != null && $main == null
}
